"auto_outcome_status": "rejected", "observed_hypothesis": "After an elite creator's signature action, teammates score more on the team's next k possessions with the same lineup on the floor.", "observed_result": "All 8 creators horizon=0. Jokic lag-1 ATT=+0.0282 CI[-0.043,+0.099] p=0.3779. CLEAN NULL on teammate PPP. Secondary: Antetokounmpo +0.075 distinct initiators over next 3 poss (perm p=0.0002, BH 0.003) ? structure not eff [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No elite creator produces a positive lineup-matched teammate-PPP lift at any lag.", "observed_sample_and_power": "Jokic lag-1 n=1880; Giannis n=1804; Doncic n=325", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF30"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.492, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-APPS-059", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.74); FAM:SF-APPS-059 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}, {"rel": "auto_related_family", "node": "FAM:SF17"}]}, {"id": "FAM:SF-APPM-054", "label": "Study family SF-APPM-054: Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "score": 0.47, "reached_via": ["request matches RQC:RQC-029 (0.70); FAM:SF-APPM-054 auto_addresses_question RQC:RQC-029", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.74); FAM:SF-APPM-054 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "auto_outcome_status": "rejected", "observed_hypothesis": "Pivoting to a listed counter after suppression sustains higher PPP than not pivoting, consistently across playoff matchups.", "observed_result": "10/12 pairs CONSISTENT and within 0.10 of non-pivot (no PIVOT_WINS). PNR->PULL_UP sustained 1.069 vs non_pivot 1.224 (n_matchups=9) PIVOT_LOSES. DRIVE->PULL_UP 1.101 vs 1.217 (n=5) PIVOT_LOSES. Largest positive pair in t [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Population deltas mostly |d|<0.10; two pairs with enough signal are PIVOT_LOSES (pivot worse than staying).", "observed_sample_and_power": "n=74 matchups; pair n_matchups 5 to 44"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPM-033"}]}], "n_results": 10}

